"""Persistent read-only Strategy A forward-paper web dashboard."""
from __future__ import annotations
import argparse,json,math
from http.server import ThreadingHTTPServer,BaseHTTPRequestHandler
import pandas as pd
from quant_bot.config import RISK_PROFILES
from quant_bot.forward.monitor import build_profile_report
from quant_bot.forward.store import ForwardStateStore

def _v(v):
    if isinstance(v,float) and (math.isnan(v) or math.isinf(v)): return None
    if hasattr(v,"item"): return _v(v.item())
    return str(v) if isinstance(v,pd.Timestamp) else v
def _rows(d): return [{k:_v(v) for k,v in r.items()} for r in d.to_dict("records")]
def snapshot(path):
    s=ForwardStateStore(path)
    try:
        f=s.report_frames(); bars=pd.read_sql_query("select * from bars order by close_time",s.connection); rep=build_profile_report(s)
        ex,dec,sig,pos,sn,ev=f["executions"],f["decisions"],f["signals"],f["positions"],f["snapshots"],f["data_events"]
        now=pd.Timestamp.now(tz="UTC"); last=pd.to_datetime(bars.close_time,utc=True).max() if len(bars) else None; disconnected=last is None or (now-last).total_seconds()>180
        profiles=[]
        for r in rep.to_dict("records"):
            p=r["profile"]; x=ex[ex.profile.eq(p)]; cfg=RISK_PROFILES[p]; closed=x[x.paper_pnl.notna()]; pnl=pd.to_numeric(closed.paper_pnl); et=pd.to_datetime(closed.exit_time,utc=True)
            r.update(total_return_pct=(r["realized_equity"]/100000-1)*100,today_pnl=float(pnl[et>=now.floor('D')].sum()),pnl_7d=float(pnl[et>=now-pd.Timedelta(days=7)].sum()),pnl_30d=float(pnl[et>=now-pd.Timedelta(days=30)].sum()),fees=float(pd.to_numeric(x.fees,errors='coerce').fillna(0).sum()),risk_per_trade=cfg['risk_pct'],open_risk_cap=cfg['max_portfolio_open_risk'],gross_cap=cfg['max_gross_exposure'],edge_sample_status='SUFFICIENT' if len(closed)>=30 else 'INSUFFICIENT SAMPLE')
            profiles.append({k:_v(v) for k,v in r.items()})
        symbols=[]
        for (p,y),g in ex[ex.paper_pnl.notna()].groupby(['profile','symbol']):
            z=pd.to_numeric(g.paper_pnl); symbols.append({'profile':p,'symbol':y,'trades':len(g),'pnl':z.sum(),'pf':z[z>0].sum()/-z[z<0].sum() if (z<0).any() else None,'win_rate':(z>0).mean(),'avg_trade':z.mean(),'stop_rate':(g.exit_reason=='stop').mean(),'trailing_rate':(g.exit_reason=='trailing').mean()})
        return {'generated_at':now.isoformat(),'historical':{'pf':1.404,'cagr':63.936,'maxdd':-14.077,'calmar':4.542},'health':{'status':'ERROR' if disconnected else 'RUNNING','connection':'DISCONNECTED' if disconnected else 'CONNECTED','last_market_update':_v(last),'last_signal':_v(pd.to_datetime(sig.signal_received_at,utc=True).max()) if len(sig) else None,'paper_mode':True,'live_orders':'DISABLED','baseline':'FIXED','anomalies':len(ev)},'profiles':profiles,'curves':{p:_rows(sn[sn.profile.eq(p)].sort_values('timestamp')) for p in RISK_PROFILES},'positions':_rows(pos),'trades':_rows(ex.sort_values('bar_timestamp',ascending=False).head(200)),'signals':_rows(sig.merge(dec,on='signal_id',how='left')) if len(sig) else [],'symbols':[{k:_v(v) for k,v in r.items()} for r in symbols],'activity':_rows(ev.sort_values('observed_at',ascending=False).head(50))}
    finally:s.close()

HTML='''<!doctype html><meta name=viewport content="width=device-width,initial-scale=1"><title>Strategy A Forward Paper</title><style>body{margin:auto;max-width:1500px;padding:16px;background:#0b1017;color:#e8eef6;font:14px system-ui}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.card{background:#151c26;border:1px solid #304055;border-radius:9px;padding:13px;margin:10px 0;overflow:auto}.m{display:flex;justify-content:space-between;border-bottom:1px solid #293747;padding:5px}table{width:100%;border-collapse:collapse;white-space:nowrap}td,th{padding:7px;border-bottom:1px solid #293747;text-align:right}td:first-child,th:first-child{text-align:left}.bad{color:#ff6474}.good{color:#43d17d}@media(max-width:800px){.grid{grid-template-columns:1fr}body{padding:8px}}</style><h1>STRATEGY A — FORWARD PAPER</h1><div id=h></div><div id=p class=grid></div><div class=card><h2>PROFILE COMPARISON</h2><div id=c></div></div><div class=grid><div class=card><h2>OPEN POSITIONS</h2><div id=o></div></div><div class=card><h2>EXECUTION / HEALTH</h2><div id=q></div></div><div class=card><h2>ACTIVITY</h2><div id=a></div></div></div><div class=card><h2>RECENT TRADES</h2><div id=t></div></div><div class=card><h2>SYMBOL BREAKDOWN</h2><div id=y></div></div><div class=card><h2>SIGNAL STREAM</h2><div id=s></div></div><script>let F=v=>v==null?'—':Number(v).toLocaleString(undefined,{maximumFractionDigits:2}),M=v=>v==null?'—':'$'+F(v),T=(cs,rs)=>'<table><tr>'+cs.map(c=>'<th>'+c[0]+'</th>').join('')+'</tr>'+rs.map(r=>'<tr>'+cs.map(c=>'<td>'+c[1](r)+'</td>').join('')+'</tr>').join('')+'</table>';async function L(){let d=await fetch('/api/snapshot',{cache:'no-store'}).then(r=>r.json());h.innerHTML=`<b class=${d.health.status==='RUNNING'?'good':'bad'}>${d.health.status}</b> · DATA ${d.health.connection} · LAST ${d.health.last_market_update||'—'} · LIVE ORDERS DISABLED · PAPER TRUE · BASELINE FIXED`;p.innerHTML=d.profiles.map(x=>`<div class=card><h2>${x.profile.toUpperCase()}</h2>${[['Equity',M(x.realized_equity)],['Return',F(x.total_return_pct)+'%'],['Today',M(x.today_pnl)],['7D',M(x.pnl_7d)],['30D',M(x.pnl_30d)],['MaxDD',F(x.max_drawdown*100)+'%'],['PF',F(x.pf)],['Expectancy',M(x.expectancy)],['Win rate',F(x.win_rate*100)+'%'],['Trades',x.trades],['Positions',x.open_positions],['Open risk',F(x.open_risk*100)+' / '+F(x.open_risk_cap*100)+'%'],['Gross',F(x.gross_exposure)+' / '+F(x.gross_cap)+'x'],['EdgeRetention',x.edge_sample_status==='SUFFICIENT'?F(x.edge_retention):x.edge_sample_status]].map(z=>`<div class=m><span>${z[0]}</span><b>${z[1]}</b></div>`).join('')}</div>`).join('');let C=[['Profile',x=>x.profile],['Equity',x=>M(x.realized_equity)],['PnL',x=>M(x.realized_equity-100000)],['PF',x=>F(x.pf)],['MaxDD',x=>F(x.max_drawdown*100)+'%'],['Trades',x=>x.trades],['Open risk',x=>F(x.open_risk*100)+'%'],['Gross',x=>F(x.gross_exposure)+'x'],['Fees',x=>M(x.fees)]];c.innerHTML=T(C,d.profiles);o.innerHTML=d.positions.length?T([['Profile',x=>x.profile],['Symbol',x=>x.symbol],['Entry',x=>F(x.paper_entry)],['Stop',x=>F(x.paper_stop)],['Notional',x=>M(x.notional)],['Risk',x=>M(x.risk_dollar)],['Signal',x=>x.signal_id]],d.positions):'No open positions';let n=d.profiles.find(x=>x.profile==='normal');q.innerHTML=`Spread ${F(n.avg_spread_bps)} bps<br>Slippage ${F(n.avg_simulated_slippage_bps)} bps<br>Signal latency ${F(n.avg_signal_latency_ms)} ms<br>Data latency ${F(n.avg_data_latency_ms)} ms<br>ExecutionDrag ${M(n.execution_drag)}<br>Anomalies ${d.health.anomalies}`;a.innerHTML=d.activity.map(x=>`${x.observed_at} · ${x.event_type}<br>`).join('')||'No activity';t.innerHTML=d.trades.length?T([['Time',x=>x.exit_time||x.entry_time],['Symbol',x=>x.symbol],['Profile',x=>x.profile],['Entry',x=>F(x.paper_fill_price)],['Exit',x=>F(x.paper_exit)],['PnL',x=>M(x.paper_pnl)],['Reason',x=>x.exit_reason||x.rejected_signal_reason],['Signal',x=>x.signal_id]],d.trades):'No trades';y.innerHTML=d.symbols.length?T([['Profile/Symbol',x=>x.profile+' / '+x.symbol],['Trades',x=>x.trades],['PnL',x=>M(x.pnl)],['PF',x=>F(x.pf)],['Win%',x=>F(x.win_rate*100)],['Stops',x=>F(x.stop_rate*100)],['Trailing',x=>F(x.trailing_rate*100)]],d.symbols):'Insufficient sample';s.innerHTML=d.signals.length?T([['Signal',x=>x.signal_id],['Symbol',x=>x.symbol],['Profile',x=>x.profile],['Status',x=>x.status],['Reason',x=>x.reason]],d.signals):'No signals yet'}L();setInterval(L,10000)</script>'''
def serve(state,host='127.0.0.1',port=5000):
 class H(BaseHTTPRequestHandler):
  def do_GET(self):
   try:b=(json.dumps(snapshot(state),default=_v) if self.path.startswith('/api/') else HTML).encode();self.send_response(200);self.send_header('Content-Type','application/json' if self.path.startswith('/api/') else 'text/html; charset=utf-8');self.send_header('Cache-Control','no-store');self.end_headers();self.wfile.write(b)
   except Exception as e:self.send_response(500);self.end_headers();self.wfile.write(str(e).encode())
  def log_message(self,*a):pass
 print(f'http://{host}:{port}');ThreadingHTTPServer((host,port),H).serve_forever()
def main():
 p=argparse.ArgumentParser();p.add_argument('--state',default='docs/forward_paper/forward_state.sqlite3');p.add_argument('--host',default='127.0.0.1');p.add_argument('--port',type=int,default=5000);a=p.parse_args();serve(a.state,a.host,a.port)
if __name__ == '__main__': main()
